import {TouchableOpacity, View} from 'react-native';
import TextCM from '../../components/Text';
import styles from './styles';
import {useAppDispatch, useAppSelector} from '../../../hooks/useRedux';
import {useTranslation} from 'react-i18next';
import {IconCheckmarkCircle} from '../../../assets/images';
import {useAccountSettingService} from '../../../hooks/apiHooks/useAccountInfoServices';
import Toast from 'react-native-toast-message';
import {accountActions, commonActions} from '../../../redux/slices';
import {ServiceIdApp} from '../../../model/enum/common.enum';
import {Icon, Spinner} from '@ui-kitten/components';
import {useState} from 'react';

const TranferOrganization = () => {
  const {dataAccount} = useAppSelector(state => state.account);
  const {t} = useTranslation();
  const AccountSettingServices = useAccountSettingService();
  const dispatch = useAppDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const handleTransferOrganization = async (orgIn: string) => {
    if (orgIn === dataAccount?.orgIn) return;
    try {
      let data = await AccountSettingServices.subOrg(
        dataAccount?.email || '',
        orgIn,
        '',
      );
      if (!data) {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
        return;
      }
      dispatch(commonActions.setAccessToken(data?.access_token));
      dispatch(accountActions.setInfoResponseLogin(data));
      dispatch(accountActions.fetchAccount());
      Toast.show({
        type: 'success',
        text1: t('ST.TxtChangeOrgSuccess'),
      });
      await AccountSettingServices.getMenuView(ServiceIdApp.EACCOUNT);
    } catch (error) {}
  };

  const handleSetDefaultOrg = async (orgIn: string) => {
    if (orgIn === dataAccount?.orgIn) return;
    try {
      setIsLoading(true);
      const dataResp = await AccountSettingServices.setDefaultOrg(orgIn);
      if (dataResp) {
        await handleTransferOrganization(orgIn);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };
  return (
    <View style={styles.menuContainer}>
      <TextCM style={styles.sectionTitle}>{t('ST.TxtOrganization')}</TextCM>
      <View
        style={{
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'space-between',
          columnGap: 10,
        }}>
        <TouchableOpacity
          style={[
            styles.menuItem,
            dataAccount.organization?.orgIn === dataAccount?.orgIn && {
              borderLeftWidth: 8,
              borderLeftColor: '#943cdd',
              borderRightWidth: 8,
              borderRightColor: '#943cdd',
            },
          ]}
          onPress={() =>
            handleTransferOrganization(dataAccount?.organization?.orgIn)
          }>
          <TextCM
            style={[
              {
                color:
                  dataAccount?.organization?.orgIn === dataAccount?.orgIn
                    ? '#943cdd'
                    : 'black',
              },
              styles.txtOrg,
            ]}>
            {dataAccount?.organization?.name}
          </TextCM>
          {dataAccount?.organization?.orgIn === dataAccount?.orgIn ? (
            <IconCheckmarkCircle
              width={24}
              height={24}
              fill={'#943cdd'}
              style={{paddingHorizontal: 5}}
            />
          ) : null}
        </TouchableOpacity>
        {!isLoading ? (
          <TouchableOpacity
            onPress={() => handleSetDefaultOrg(dataAccount.organization?.orgIn)}
            style={{marginBottom: 15}}>
            <Icon
              name="star"
              width={24}
              height={24}
              fill={
                dataAccount?.organization?.orgIn === dataAccount?.defaultOrgIn
                  ? '#facc15'
                  : '#000000de'
              }
            />
          </TouchableOpacity>
        ) : (
          <Spinner />
        )}
      </View>
      <TextCM style={styles.sectionTitle}>{t('ST.TxtSubOrganization')}</TextCM>
      {dataAccount?.subOrganizations?.length > 0 ? (
        dataAccount?.subOrganizations.map((subOrg: any) => (
          <View
            key={subOrg?.orgIn}
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'space-between',
              columnGap: 10,
            }}>
            <TouchableOpacity
              style={[
                styles.menuItem,
                subOrg?.orgIn === dataAccount?.orgIn && {
                  borderLeftWidth: 8,
                  borderLeftColor: '#943cdd',
                  borderRightWidth: 8,
                  borderRightColor: '#943cdd',
                },
              ]}
              onPress={() => handleTransferOrganization(subOrg?.orgIn)}>
              <TextCM
                style={{
                  color:
                    subOrg?.orgIn === dataAccount?.orgIn ? '#943cdd' : 'black',
                }}>
                {subOrg?.name}
              </TextCM>
              {subOrg?.orgIn === dataAccount?.orgIn ? (
                <IconCheckmarkCircle
                  width={24}
                  height={24}
                  fill={'#943cdd'}
                  style={{paddingHorizontal: 5}}
                />
              ) : null}
            </TouchableOpacity>

            {!isLoading ? (
              <TouchableOpacity
                onPress={() => handleSetDefaultOrg(subOrg?.orgIn)}
                style={{marginBottom: 15}}>
                <Icon
                  name="star"
                  width={24}
                  height={24}
                  fill={
                    subOrg?.orgIn === dataAccount?.defaultOrgIn
                      ? '#facc15'
                      : '#000000de'
                  }
                />
              </TouchableOpacity>
            ) : (
              <Spinner />
            )}
          </View>
        ))
      ) : (
        <TextCM>{t('ST.TxtNoSubOrg')}</TextCM>
      )}
    </View>
  );
};

export default TranferOrganization;
